# Source for q/ae-measure.js: Measurements (chamber quantification, Doppler calculations), Echo views.
# Normal values from ASE/EACVI 2015 chamber quantification unless noted.
M="Measurements"; EV="Echo views"
Q=[
# --- LV linear and mass ---
(M,"Normal LV end-diastolic diameter in women (2D) is about:","3.8 to 5.2 cm",["2.0 to 3.0 cm","5.5 to 7.0 cm","7.0 to 8.0 cm"],"In men it is about 4.2 to 5.8 cm.","F"),
(M,"Normal end-diastolic septal and posterior wall thickness in men is about:","0.6 to 1.0 cm",["0.2 to 0.5 cm","1.2 to 1.6 cm","2.0 cm or more"],"In women it is about 0.6 to 0.9 cm.","F"),
(M,"LV linear measurements by 2D should be made:","At end-diastole, at the level of the mitral leaflet tips, perpendicular to the LV long axis",["At end-systole at the apex","Diagonally through the papillary muscles","At the aortic annulus"],"End-systolic diameter is measured at the same level at the smallest cavity size.","F"),
(M,"The ASE linear method for LV mass uses:","Septal thickness, LV internal diameter and posterior wall thickness at end-diastole",["LA volume and RV size","Aortic root diameter only","Mitral E and A velocities"],"LV mass = 0.8 × 1.04 × [(IVS + LVID + PW)³ − LVID³] + 0.6 g. Errors in each measurement are cubed.","F"),
(M,"Why is LV mass very sensitive to small measurement errors?","The linear formula cubes the measurements",["It uses Doppler","It depends on heart rate","It uses only one measurement"],"A 1 mm error in wall thickness can change mass significantly.","C"),
(M,"LV mass is indexed to:","Body surface area",["Heart rate","Blood pressure","Age only"],"Normal LV mass index is up to about 95 g/m² in women and 115 g/m² in men.","F"),
(M,"IVSd 1.0 cm, LVIDd 5.0 cm and PWd 1.0 cm. What is the relative wall thickness?","0.40",["0.20","0.80","1.00"],"RWT = 2 × PW ÷ LVID = 2 × 1.0 ÷ 5.0 = 0.40, which is normal (0.42 or less).","C"),
# --- LV volumes ---
(M,"Normal indexed LV end-diastolic volume (biplane) in men is up to about:","74 mL/m²",["30 mL/m²","120 mL/m²","150 mL/m²"],"In women the upper limit is about 61 mL/m².","C"),
(M,"Normal indexed LV end-systolic volume in women is up to about:","24 mL/m²",["5 mL/m²","61 mL/m²","100 mL/m²"],"In men it is about 31 mL/m². Increased ESV is a strong predictor of outcome.","C"),
(M,"Why do 2D volumes often underestimate LV size compared with 3D or MRI?","Apical views are often foreshortened and miss the true apex",["2D always overestimates","Doppler is used","Harmonics shrink the cavity"],"3D echo, when image quality allows, is preferred for volumes.","F"),
(M,"The biplane method of disks calculates volume by:","Summing many elliptical disks from orthogonal A4C and A2C traces",["Cubing one diameter","Multiplying VTI by area","Measuring only the LV length"],"It works even when the LV shape is distorted.","F"),
(M,"The area-length method for LV volume assumes the LV shape is:","A bullet (prolate ellipsoid)",["A perfect cube","A cylinder","A sphere"],"Volume = 5/6 × area × length. It is used when only one good view is available.","C"),
# --- LA / RA ---
(M,"LA volume is measured at:","End-systole, just before the mitral valve opens, when the LA is largest",["End-diastole","Mid-diastole","During atrial contraction"],"Exclude the pulmonary veins and LA appendage from the trace.","F"),
(M,"LA volume is 76 mL and body surface area is 2.0 m². What is the LA volume index?","38 mL/m², enlarged",["38 mL/m², normal","152 mL/m²","19 mL/m²"],"76 ÷ 2.0 = 38 mL/m², above the normal limit of 34 mL/m².","C"),
(M,"Why is LA volume preferred to LA anteroposterior diameter?","The LA can enlarge unevenly, so one diameter may miss enlargement",["Diameter is more accurate","Volume uses Doppler","Diameter is measured in diastole"],"The LA often enlarges up and sideways, restricted front-to-back by the sternum and spine.","F"),
(M,"Normal right atrial area (apical four-chamber, end-systole) is up to about:","18 cm²",["5 cm²","30 cm²","50 cm²"],"Trace from the tricuspid annulus around the RA, excluding the IVC and appendage.","F"),
(M,"The LA trace for volume should exclude:","The pulmonary veins and left atrial appendage",["The atrial septum","The mitral annulus","The LA roof"],"Close the trace straight across the mitral annulus.","F"),
# --- RV ---
(M,"An RV basal diameter greater than about 4.1 cm in the RV-focused view suggests:","RV dilation",["Normal RV","RV hypertrophy","LV dilation"],"Mid-RV diameter over about 3.5 cm also suggests dilation.","F"),
(M,"A proximal RVOT diameter greater than about 3.0 cm in the parasternal long-axis view suggests:","RV outflow dilation",["Normal size","Pulmonic stenosis","LV hypertrophy"],"RVOT size helps assess conditions such as ARVC and pulmonic regurgitation.","C"),
(M,"Tissue Doppler RV s′ velocity below about 9.5 cm/s suggests:","RV systolic dysfunction",["Normal RV function","Pulmonary hypertension only","LV dysfunction"],"Measure at the lateral tricuspid annulus in the apical four-chamber view, aligned with motion.","F"),
(M,"RV free wall longitudinal strain is abnormal when it is less negative than about:","−20%",["−50%","−5%","+20%"],"A free wall strain of −15% means reduced RV function.","C"),
(M,"RV wall thickness is measured:","In the subcostal view at end-diastole, at the level of the tricuspid chordae",["In the apical two-chamber view","In PLAX at end-systole","At the RV apex"],"Over 5 mm suggests RV hypertrophy.","C"),
# --- Aorta, LVOT ---
(M,"The aortic annulus and LVOT are measured:","In mid-systole, inner edge to inner edge",["At end-diastole, leading edge to leading edge","At end-systole only","During atrial contraction"],"Aortic root and ascending aorta are measured at end-diastole, leading edge to leading edge.","F"),
(M,"The LVOT diameter for continuity calculations is measured:","In a zoomed parasternal long-axis view, at or near the aortic annulus",["In the apical four-chamber view","In the subcostal view","In PSAX at the papillary muscles"],"The PW sample volume for LVOT VTI should be placed at the same level.","F"),
(M,"A normal LVOT VTI is about:","18 to 22 cm",["5 to 8 cm","40 to 60 cm","100 cm"],"A VTI under about 15 cm suggests low stroke volume.","F"),
(M,"Stroke volume index below 35 mL/m² defines:","Low flow, important in low-gradient aortic stenosis",["Normal flow","High flow","Severe AR"],"Low flow can make severe AS look moderate by gradient.","F"),
# --- Doppler calculations ---
(M,"LVOT VTI is 20 cm and aortic valve VTI is 100 cm. What is the dimensionless index?","0.20",["5.0","0.80","2.0"],"20 ÷ 100 = 0.20, consistent with severe AS (under 0.25).","F"),
(M,"LVOT diameter 2.2 cm, LVOT VTI 18 cm, AV VTI 90 cm. What is the aortic valve area?","About 0.76 cm²",["About 3.8 cm²","About 1.5 cm²","About 0.38 cm²"],"LVOT area = 0.785 × 2.2² = 3.80 cm². AVA = 3.80 × 18 ÷ 90 ≈ 0.76 cm².","C"),
(M,"Mitral PHT is 200 ms. What is the estimated mitral valve area?","1.1 cm²",["2.2 cm²","0.9 cm²","4.4 cm²"],"MVA = 220 ÷ 200 = 1.1 cm².","F"),
(M,"PISA radius 1.0 cm, aliasing velocity 40 cm/s, MR peak velocity 500 cm/s. What is the EROA?","About 0.50 cm²",["About 0.25 cm²","About 1.0 cm²","About 0.08 cm²"],"Flow = 2π × 1² × 40 ≈ 251 mL/s. EROA = 251 ÷ 500 ≈ 0.50 cm², consistent with severe MR.","C"),
(M,"Using EROA 0.5 cm² and MR VTI 150 cm, what is the regurgitant volume?","75 mL",["30 mL","150 mL","300 mL"],"Regurgitant volume = EROA × VTI = 0.5 × 150 = 75 mL, consistent with severe MR.","C"),
(M,"Mitral inflow stroke volume is 120 mL and LVOT stroke volume is 70 mL. What is the regurgitant fraction?","About 42%",["About 58%","About 70%","About 17%"],"Regurgitant volume = 120 − 70 = 50 mL. RF = 50 ÷ 120 ≈ 42%.","C"),
(M,"PISA radius is most accurately measured:","From the leaflet orifice to the first aliasing boundary, in mid-systole with the baseline shifted toward the jet",["From the LA roof","At end-diastole","Without zoom"],"The radius is squared, so small errors matter.","C"),
(M,"PR end-diastolic velocity is 2 m/s and RA pressure is 5 mmHg. What is the estimated PA diastolic pressure?","21 mmHg",["16 mmHg","9 mmHg","41 mmHg"],"PADP = 4 × 2² + 5 = 21 mmHg.","C"),
(M,"Mitral E 100 cm/s, septal e′ 6 cm/s and lateral e′ 8 cm/s. What is the average E/e′?","About 14",["About 12","About 17","About 7"],"Average e′ = 7 cm/s. 100 ÷ 7 ≈ 14.3, borderline raised filling pressure.","C"),
(M,"Heart rate 70 bpm, LVOT diameter 2.0 cm and LVOT VTI 20 cm. What is the cardiac output?","About 4.4 L/min",["About 6.3 L/min","About 1.4 L/min","About 2.2 L/min"],"SV = 3.14 × 20 ≈ 63 mL. CO = 63 × 70 ≈ 4,400 mL/min.","C"),
(M,"In atrial fibrillation, Doppler measurements should be:","Averaged over at least 5 beats",["Taken from the single best beat","Taken from 1 beat only","Avoided completely"],"Beat-to-beat variation in stroke volume is large in AF.","F"),
(M,"In sinus rhythm, Doppler velocities are typically averaged over:","3 beats",["10 beats","1 beat","20 beats"],"Use the window that gives the highest velocity for valve stenosis.","F"),
(M,"Mitral valve area by continuity in MS is calculated as:","LVOT area × LVOT VTI ÷ mitral inflow VTI",["220 ÷ PHT","4 × velocity²","EROA × VTI"],"It is invalid with significant MR or AR.","C"),
(M,"Normal mitral E-wave deceleration time in adults is about:","160 to 240 ms",["50 to 80 ms","300 to 400 ms","500 ms"],"A short DT (under about 160 ms) with raised E suggests high filling pressure.","F"),
(M,"Normal IVRT in adults is about:","70 to 100 ms",["10 to 20 ms","200 to 300 ms","Under 30 ms"],"Prolonged IVRT suggests impaired relaxation; short IVRT suggests high LA pressure.","F"),
(M,"Normal peak aortic valve velocity in adults is about:","1.0 to 1.7 m/s",["3.5 to 4.5 m/s","0.1 to 0.3 m/s","Over 5 m/s"],"A peak velocity of 2.0 m/s or more suggests at least mild obstruction or high flow.","F"),
(M,"Normal pulmonary vein flow in a young adult shows:","S wave and D wave, with S often equal to or higher than D, and a small Ar reversal",["Only an Ar wave","Systolic reversal","Continuous flow with no waves"],"Young people with brisk relaxation can have D greater than S normally.","F"),
(M,"MAPSE (mitral annular plane systolic excursion) below about 10 mm suggests:","Reduced LV longitudinal function",["Normal LV function","Mitral stenosis","LV hypertrophy only"],"It is an M-mode measurement from the apical view.","C"),
(M,"Strain is defined as:","The fractional change in length of a segment of myocardium",["Velocity of the myocardium","Pressure in the LV","Volume of the LV"],"Longitudinal shortening is reported as a negative percentage. Strain rate is how fast it changes.","F"),
(M,"Speckle-tracking strain is less angle-dependent than tissue Doppler because it:","Tracks natural speckle patterns in 2D rather than measuring velocity along the beam",["Uses CW Doppler","Uses only M-mode","Requires contrast"],"It needs good image quality and adequate frame rate.","F"),
(M,"The IVC diameter is measured:","In the subcostal view, within 1 to 2 cm of the RA junction, perpendicular to its long axis",["In PLAX","In the suprasternal view","At the hepatic veins only"],"Measure at end-expiration and with a sniff.","F"),
(M,"An IVC diameter of 1.8 cm that collapses more than 50% with a sniff suggests RA pressure of about:","3 mmHg",["8 mmHg","15 mmHg","25 mmHg"],"Normal RA pressure is 0 to 5 mmHg.","F"),
(M,"An IVC diameter of 2.4 cm that collapses more than 50% with a sniff suggests RA pressure of about:","8 mmHg (intermediate)",["3 mmHg","15 mmHg","0 mmHg"],"Mixed findings fall into the intermediate category; other signs refine it.","C"),
(M,"A TR peak velocity of 3.2 m/s with an RA pressure of 8 mmHg gives an RVSP of about:","49 mmHg",["41 mmHg","33 mmHg","20 mmHg"],"4 × 3.2² = 41; 41 + 8 ≈ 49 mmHg.","C"),
(M,"Mean pressure gradient across a valve should be obtained by:","Tracing the full velocity envelope",["Using the peak velocity only","Measuring at one point","Halving the peak gradient"],"The machine averages the instantaneous gradients across the traced area.","F"),
(M,"Before measuring an aortic stenosis jet, the sonographer should use:","All available windows, including the right parasternal, to find the highest velocity",["The apical window only","PW Doppler only","Color Doppler only"],"Underestimating peak velocity underestimates severity.","F"),
(M,"Reporting the heart rate with mitral stenosis gradients is important because:","Mean gradient rises strongly with heart rate",["Gradient falls with heart rate","Heart rate doesn't affect MS","It changes the PHT formula"],"Shorter diastole at faster rates needs a higher gradient to fill the LV.","F"),
(M,"Which measurement should be indexed to body surface area for comparison?","LA volume",["TR velocity","Mitral E velocity","Heart rate"],"LV volumes, LV mass and aortic valve area are also indexed.","F"),
(M,"Body surface area is calculated from:","Height and weight",["Age and sex","Heart rate","Blood pressure"],"Common formulas include Mosteller and DuBois.","F"),
(M,"A biplane LV EF uses EDV 120 mL and ESV 54 mL. What is the EF?","55%",["45%","66%","35%"],"EF = (120 − 54) ÷ 120 = 66 ÷ 120 = 55%.","F"),
(M,"Visual estimation of EF is acceptable when:","It is done by experienced readers, though quantitative methods are preferred",["It replaces all measurements always","The image is foreshortened","The patient is in AF"],"Report quantitative EF when image quality allows.","F"),
(M,"Wall motion score index of 1.0 means:","All segments move normally",["All segments are akinetic","Severe dysfunction","The study is uninterpretable"],"Higher scores mean more segments are abnormal.","F"),
(M,"AR pressure half-time is measured from:","CW Doppler of the AR jet, tracing the slope of the diastolic signal",["PW in the LVOT","Mitral inflow","Color Doppler only"],"Shorter PHT means faster pressure equalization and more severe AR.","F"),
(M,"Vena contracta width is measured:","At the narrowest neck of the jet just beyond the orifice, in a zoomed view",["At the widest part of the jet","At the back of the LA","In the LV"],"Use a view perpendicular to the coaptation line and a narrow color sector.","F"),
(M,"Proximal isovelocity surface area (PISA) assumes the flow converges in a:","Hemispheric shell",["Perfect cube","Flat disk","Cylinder"],"Flat or constrained convergence surfaces cause errors.","C"),
(M,"For LVOT stroke volume, a 1 mm error in LVOT diameter of 2.0 cm leads to an area error of about:","10%",["1%","50%","0%"],"Area depends on diameter squared: (2.1 ÷ 2.0)² ≈ 1.10.","C"),
# --- Measurement views and technique ---
(EV,"The best view for measuring LVOT diameter is:","Zoomed parasternal long axis",["Apical four-chamber","Subcostal four-chamber","Suprasternal long axis"],"Axial resolution along the beam is better than lateral resolution, and the LVOT lies perpendicular to the beam in PLAX.","F"),
(EV,"The best view for recording the LVOT PW Doppler signal is:","Apical five-chamber or three-chamber",["Parasternal long axis","Parasternal short axis","Subcostal short axis"],"Flow is parallel to the beam from the apex.","F"),
(EV,"The best view for measuring the RV basal diameter is:","RV-focused apical four-chamber",["Parasternal long axis","Suprasternal view","Apical two-chamber"],"Standard A4C views can cut the RV obliquely and underestimate it.","F"),
(EV,"Mitral regurgitation vena contracta is best measured in:","Parasternal long-axis view",["Apical two-chamber view only","Subcostal view","Suprasternal view"],"Avoid the A2C view, which runs parallel to the coaptation line and overestimates width.","C"),
(EV,"Which view is used for color M-mode flow propagation (Vp)?","Apical four-chamber, with the M-mode line through the mitral inflow to the apex",["Parasternal short axis","Subcostal","Suprasternal"],"Narrow the color sector and shift the baseline to show the first aliasing velocity.","C"),
(EV,"Which view is best for measuring LA anteroposterior diameter?","Parasternal long axis at end-systole",["Apical two-chamber","Subcostal","Suprasternal"],"Volume from apical views is preferred for size assessment.","F"),
(EV,"Which window usually gives the best TR jet alignment in a patient with RV dilation?","Apical or RV-focused apical view, sometimes the parasternal RV inflow view",["Suprasternal","Right parasternal","Subcostal IVC view"],"Check several windows and report the highest good-quality velocity.","F"),
(EV,"Aortic regurgitation jet width is measured in:","Parasternal long axis, just below the aortic valve",["Apical four-chamber","Subcostal","Suprasternal"],"Compare jet width with LVOT width at the same level.","F"),
(EV,"Holodiastolic flow reversal in the abdominal aorta is recorded from the:","Subcostal window",["Apical window","Parasternal window","Right parasternal window"],"It is a specific sign of severe AR.","F"),
(EV,"To align Doppler with the descending thoracic aorta for AR reversal, use the:","Suprasternal notch view",["Apical four-chamber view","Parasternal short axis","Subcostal four-chamber"],"Place the PW sample in the proximal descending aorta just beyond the left subclavian artery.","F"),
(EV,"Pulmonic valve and RVOT Doppler is usually recorded in the:","Parasternal short-axis view at the aortic level or the RVOT view",["Apical two-chamber view","Suprasternal view","Subcostal IVC view"],"In thin patients, the subcostal short-axis view can also align with the RVOT.","F"),
(EV,"Which view best shows the LV apex for thrombus?","Apical views zoomed on the apex, with a higher frequency or contrast",["Parasternal long axis only","Suprasternal view","Subcostal IVC view"],"Off-axis and foreshortened views easily miss apical thrombus.","F"),
(EV,"The parasternal short-axis view at the mitral valve level is used to measure:","Mitral valve area by planimetry",["LVOT diameter","IVC size","Aortic arch"],"Find the smallest orifice at the leaflet tips.","F"),
(EV,"Which view is preferred for the LA appendage on transthoracic echo?","Parasternal short axis at the aortic level or apical two-chamber, though TTE often misses it",["Subcostal IVC view","Suprasternal arch","Right parasternal"],"TEE is needed to exclude LAA thrombus reliably.","C"),
(EV,"Which view is used for hepatic vein Doppler to grade TR?","Subcostal",["Parasternal long axis","Apical two-chamber","Suprasternal"],"Sample 1 to 2 cm into a hepatic vein, aligned with flow.","F"),
(EV,"The apical two-chamber view is obtained from the apical four-chamber view by:","Rotating the transducer about 60° counterclockwise",["Rotating 60° clockwise","Tilting anteriorly","Sliding to the subcostal window"],"Rotate a further 60° to reach the apical long axis (three-chamber).","F"),
(EV,"The parasternal RV inflow view is obtained by:","Tilting the transducer inferiorly and medially from the PLAX view",["Tilting anteriorly from PLAX","Rotating to PSAX","Sliding to the apex"],"It shows the RA, RV, tricuspid valve and often the coronary sinus and IVC entry.","F"),
(EV,"The best view for measuring aortic root and ascending aorta in most adults is:","Parasternal long axis, moving up one rib space for the ascending aorta",["Apical four-chamber","Subcostal","Apical two-chamber"],"A high left or right parasternal window shows more of the ascending aorta.","F"),
]
